    roleMembers: { what: 'who holds each directory role', edges: ['AssignedRole'], analyses: ['ga', 'pra', 'caa', 'apa', 'auth', 'pwreset'], findings: ['PermanentPrivilegedRole', 'ExcessivePrivilege', 'PrivilegedGuest'], types: ['user', 'guest', 'group', 'sp', 'role'] },
    roleDefinitions: { what: 'role definitions (custom roles, isPrivileged)', edges: ['AssignedRole', 'ScopedRole'], analyses: [], findings: [], types: ['role'] },
    roleAssignments: { what: 'AU-scoped role assignments', edges: ['ScopedRole'], analyses: ['pwreset'], findings: [], types: ['role', 'au'] },
    roleEligible: { what: 'PIM eligible assignments', edges: ['EligibleRole'], analyses: ['pim'], findings: ['PimEligible'], types: ['user', 'guest', 'group', 'role'] },
    roleActivePim: { what: 'PIM time-bound active assignments', edges: [], analyses: [], findings: ['PermanentPrivilegedRole'], types: ['user', 'role'] },
