  };
  // state: collector state {key: {st, detail}}; raw.demo → everything seen.
  function gaps(raw, state){
    if(!raw || raw.demo) return [];
    var all = EH.collector.SOURCES.concat(EH.collector.PHASE2), out = [];
    all.forEach(function(src){
      var st = state[src.key]; if(!st || st.st === 'ok') return;
      var imp = IMPACT[src.key] || { what: src.label.toLowerCase(), edges: [], analyses: [], findings: [], types: [] };
      var perm = EH.auth.GROUPS[src.group].label + (src.alt ? ' or ' + EH.auth.GROUPS[src.alt].label : '');
      var reason = st.st === 'skip' ? (/not consented/.test(st.detail) ? 'permission not consented' : st.detail || 'skipped') : 'collection failed: ' + st.detail;
      out.push({ key: src.key, label: src.label, state: st.st, reason: reason, permission: perm, what: imp.what, edges: imp.edges, analyses: imp.analyses, findings: imp.findings, types: imp.types, risk: imp.risk || null });
    });
    return out;
  }
  function summary(raw, state){
    var all = EH.collector.SOURCES.concat(EH.collector.PHASE2), g = gaps(raw, state);
    var ok = all.length - g.length;
    return { total: all.length, ok: ok, gaps: g, unknown: g.map(function(x){ return x.what; }) };
  }
  function forAnalysis(g, key){ return g.filter(function(x){ return x.analyses.indexOf(key) >= 0; }); }
  function forType(g, type){ return g.filter(function(x){ return x.types.indexOf(type) >= 0; }); }
  function forFinding(g, kind){ return g.filter(function(x){ return x.findings.indexOf(kind) >= 0; }); }
  return { IMPACT: IMPACT, gaps: gaps, summary: summary, forAnalysis: forAnalysis, forType: forType, forFinding: forFinding };
})();
